/**
 * NOVA_ATELIER_WORLD — "AS FEATURED IN" brand-mark wall
 * 1. COMPOSITION: graded backdrop plane (z=-2.5) -> soft radial vignette plane (z=-1.1, depth plane 2)
 *    -> 3x2 grid of six machined tiles (1.0x0.62, gap 0.25, grid 3.5x1.49) centered at origin, kicker
 *    text 0.3 units above the grid top edge, each tile carrying a flat monochrome wordmark (depth plane 3).
 * 2. LIGHT RIG (rig-gallery-soft): key directional #fff8f0 @1.9 from [0.8,3.4,2]->[0,0.5,0]; fill
 *    hemisphere #f2eee8 @0.65; rim directional #ffffff @0.8 from [0.4,1.8,-2.8]->[0,0.6,0]; a single
 *    low-intensity accent point light (#ff2a38) grazes one tile edge for the signal sliver.
 *    Key rakes at ~35deg elevation so the brushed anisotropic highlight sweeps the tiles.
 * 3. MATERIALS: MeshPhysicalNodeMaterial per tile — roughness 0.55, metalness 0.5, clearcoat 0.2,
 *    anisotropy 0.6 aligned to x, vertical TSL albedo ramp #1a1a22->#121218; chamfer suggested via a
 *    thin bevel-edge inset box wrapping each tile. Backdrop/vignette use MeshBasicNodeMaterial.
 * 4. MOTION: mount = stagger-cards fade-up (opacity 0->1, y +0.2->0, 500ms cubic-bezier-ish power2.out,
 *    80ms stagger, top row left-to-right first). Hover = wordmark opacity 0.78->1.0 + tile z 0->0.05
 *    over 160ms. All timelines tracked and killed in cleanup.
 * 5. FOCAL ELEMENT: the top-center tile ("MONOCLE") carries a faint emissive lift and sits closest to
 *    the key light's highlight sweep peak — the single brightest read on the wall.
 */

import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, positionLocal, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new THREE.Group();
  root.name = 'nova-brand-mark-wall';

  const colors = config?.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#121218' }]
  };

  const disposables = { geometries: [], materials: [], textures: [] };
  const timelines = [];

  // ---------------------------------------------------------------
  // DEPTH PLANE 1: graded backdrop (never flat void)
  // ---------------------------------------------------------------
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#121218' }];
  const gTop = vec3(new THREE.Color(stops[0].hex).r, new THREE.Color(stops[0].hex).g, new THREE.Color(stops[0].hex).b);
  const gBottom = vec3(new THREE.Color(stops[1].hex).r, new THREE.Color(stops[1].hex).g, new THREE.Color(stops[1].hex).b);

  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const bT = float(1.0).sub(uv().y);
  backdropMat.colorNode = mix(gTop, gBottom, bT);
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.geometries.push(backdropGeo);
  disposables.materials.push(backdropMat);

  // ---------------------------------------------------------------
  // DEPTH PLANE 2: soft radial vignette (adds atmosphere behind the grid)
  // ---------------------------------------------------------------
  const vignetteGeo = new THREE.PlaneGeometry(4.4, 2.6);
  const vignetteMat = new MeshBasicNodeMaterial();
  const inkColor = new THREE.Color(colors.ink);
  vignetteMat.colorNode = vec3(inkColor.r, inkColor.g, inkColor.b);
  const d = uv().sub(vec3(0.5, 0.5, 0).xy).length();
  vignetteMat.opacityNode = smoothstep(0.15, 0.65, d).mul(0.55);
  vignetteMat.transparent = true;
  vignetteMat.depthWrite = false;
  const vignette = new THREE.Mesh(vignetteGeo, vignetteMat);
  vignette.position.set(0, -0.05, -1.1);
  root.add(vignette);
  disposables.geometries.push(vignetteGeo);
  disposables.materials.push(vignetteMat);

  // ---------------------------------------------------------------
  // LIGHT RIG (rig-gallery-soft)
  // ---------------------------------------------------------------
  const key = new THREE.DirectionalLight(new THREE.Color('#fff8f0'), 1.9);
  key.position.set(0.8, 3.4, 2);
  key.target.position.set(0, 0.5, 0);
  root.add(key, key.target);

  const fill = new THREE.HemisphereLight(new THREE.Color('#f2eee8'), new THREE.Color(colors.surface), 0.65);
  root.add(fill);

  const rim = new THREE.DirectionalLight(new THREE.Color('#ffffff'), 0.8);
  rim.position.set(0.4, 1.8, -2.8);
  rim.target.position.set(0, 0.6, 0);
  root.add(rim, rim.target);

  const accentLight = new THREE.PointLight(new THREE.Color(colors.accent), 0.35, 3.0, 2.0);
  accentLight.position.set(-1.5, 0.5, 0.6);
  root.add(accentLight);

  // ---------------------------------------------------------------
  // TEXT: kicker
  // ---------------------------------------------------------------
  const items = config.textContent ?? config?.intent?.visualSpec?.textContent ?? [
    { text: 'AS FEATURED IN', role: 'kicker' },
    { text: 'HODINKEE', role: 'brand-mark' },
    { text: 'MONOCLE', role: 'brand-mark' },
    { text: 'WALLPAPER', role: 'brand-mark' },
    { text: 'ESQUIRE', role: 'brand-mark' },
    { text: 'WIRED', role: 'brand-mark' },
    { text: 'FINANCIAL TIMES', role: 'brand-mark' }
  ];

  const kickerItem = items.find((i) => i.role === 'kicker') ?? { text: 'AS FEATURED IN' };
  const markItems = items.filter((i) => i.role === 'brand-mark');
  while (markItems.length < 6) markItems.push({ text: '' });

  const gridTotalW = 3.5;
  const gridTotalH = 1.49;
  const tileW = 1.0;
  const tileH = 0.62;
  const gap = 0.25;

  const kicker = ctx.fontAtlas.createText(kickerItem.text, {
    fontSize: 9,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 9 * 0.12
  });
  kicker.position.set(0, gridTotalH / 2 + 0.3, 0.01);
  root.add(kicker);

  // ---------------------------------------------------------------
  // TILE GRID (3 cols x 2 rows) — top row left-to-right first
  // ---------------------------------------------------------------
  const tileGroups = [];
  const focalIndex = 1; // top-center ("MONOCLE") — the single brightest element

  const gradTop = new THREE.Color(stops[0].hex);
  const gradBottom = new THREE.Color(stops[1].hex);

  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 3; col++) {
      const index = row * 3 + col;
      const x = col * (tileW + gap) - gridTotalW / 2 + tileW / 2;
      const y = row === 0 ? gridTotalH / 2 - tileH / 2 : gridTotalH / 2 - tileH / 2 - (tileH + gap);

      const tileGroup = new THREE.Group();
      tileGroup.position.set(x, y, 0);

      // chamfer suggestion: thin recessed frame behind the front face
      const chamferGeo = new THREE.BoxGeometry(tileW + 0.02, tileH + 0.02, 0.03);
      const chamferMat = new MeshPhysicalNodeMaterial();
      chamferMat.color = new THREE.Color(colors.surface).multiplyScalar(0.7);
      chamferMat.roughness = 0.7;
      chamferMat.metalness = 0.4;
      const chamfer = new THREE.Mesh(chamferGeo, chamferMat);
      chamfer.position.z = -0.02;
      tileGroup.add(chamfer);
      disposables.geometries.push(chamferGeo);
      disposables.materials.push(chamferMat);

      const tileGeo = new THREE.BoxGeometry(tileW, tileH, 0.05, 4, 4, 1);
      tileGeo.computeTangents?.();
      const tileMat = new MeshPhysicalNodeMaterial();
      tileMat.colorNode = mix(
        vec3(gradTop.r, gradTop.g, gradTop.b),
        vec3(gradBottom.r, gradBottom.g, gradBottom.b),
        float(1.0).sub(uv().y)
      );
      tileMat.roughness = 0.55;
      tileMat.metalness = 0.5;
      tileMat.clearcoat = 0.2;
      tileMat.clearcoatRoughness = 0.35;
      tileMat.anisotropy = 0.6;
      tileMat.anisotropyRotation = 0.0;
      tileMat.transparent = true;
      tileMat.opacity = 0;

      if (index === focalIndex) {
        tileMat.emissive = new THREE.Color(colors.paper);
        tileMat.emissiveIntensity = 0.06;
      }

      const tile = new THREE.Mesh(tileGeo, tileMat);
      tile.position.z = 0;
      tileGroup.add(tile);
      disposables.geometries.push(tileGeo);
      disposables.materials.push(tileMat);

      // wordmark
      const wordmark = ctx.fontAtlas.createText(markItems[index].text, {
        fontSize: 13,
        color: colors.paper,
        align: 'center',
        letterSpacingPx: 13 * 0.08
      });
      wordmark.position.set(0, 0, 0.03);
      wordmark.traverse((c) => {
        if (c.material) {
          c.material.transparent = true;
          c.material.opacity = 0;
        }
      });
      tileGroup.add(wordmark);

      // accent sliver — one tile only, kept under 10% of frame
      if (index === focalIndex) {
        const striGeo = new THREE.BoxGeometry(0.015, tileH * 0.9, 0.03);
        const striMat = new MeshPhysicalNodeMaterial();
        striMat.color = new THREE.Color(colors.accent);
        striMat.emissive = new THREE.Color(colors.accent);
        striMat.emissiveIntensity = 1.1;
        striMat.roughness = 0.4;
        striMat.metalness = 0.2;
        const stripe = new THREE.Mesh(striGeo, striMat);
        stripe.position.set(-tileW / 2 + 0.02, 0, 0.03);
        tileGroup.add(stripe);
        disposables.geometries.push(striGeo);
        disposables.materials.push(striMat);
      }

      tileGroup.position.y += 0.2; // pre-settle offset for fade-up
      root.add(tileGroup);

      tileGroups.push({
        group: tileGroup,
        tile,
        tileMat,
        wordmark,
        baseY: y,
        index
      });

      // hover handlers attached to the raycastable mesh
      tile.userData.handlers = {
        pointerenter: () => {
          gsap.to(tile.position, { z: 0.05, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
          wordmark.traverse((c) => {
            if (c.material) gsap.to(c.material, { opacity: 1.0, duration: 0.16 });
          });
        },
        pointerleave: () => {
          gsap.to(tile.position, { z: 0, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
          wordmark.traverse((c) => {
            if (c.material) gsap.to(c.material, { opacity: 0.78, duration: 0.16 });
          });
        }
      };
    }
  }

  // ---------------------------------------------------------------
  // MOUNT MOTION: stagger-cards fade-up, top row left-to-right first
  // ---------------------------------------------------------------
  const mountTl = gsap.timeline();
  tileGroups.forEach((t, i) => {
    mountTl.to(
      t.group.position,
      { y: t.baseY, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
    mountTl.to(
      t.tileMat,
      { opacity: 1, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
    t.wordmark.traverse((c) => {
      if (c.material) {
        mountTl.to(c.material, { opacity: 0.78, duration: 0.5, ease: 'power2.out' }, i * 0.08);
      }
    });
  });
  timelines.push(mountTl);

  const kickerOpacityHolder = { v: 0 };
  kicker.traverse((c) => {
    if (c.material) {
      c.material.transparent = true;
      c.material.opacity = 0;
    }
  });
  const kickerTl = gsap.timeline();
  kicker.traverse((c) => {
    if (c.material) {
      kickerTl.to(c.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
    }
  });
  timelines.push(kickerTl);

  // ---------------------------------------------------------------
  // root-level generic handlers (defensive aggregate)
  // ---------------------------------------------------------------
  root.userData.handlers = {
    pointerenter: () => {},
    pointerleave: () => {}
  };

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.geometries.forEach((g) => g.dispose());
    disposables.materials.forEach((m) => m.dispose());
    disposables.textures.forEach((t) => t.dispose());
    root.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose?.();
        if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose?.());
        else obj.material?.dispose?.();
      }
    });
  };

  return root;
}

