  {"id":"text.brand-mark.1","where":"createNode/TILE GRID loop","how":"markItems[0] HODINKEE wordmark on tile 0"},
  {"id":"text.brand-mark.2","where":"createNode/TILE GRID loop","how":"markItems[1] MONOCLE wordmark on focal tile"},
  {"id":"text.brand-mark.3","where":"createNode/TILE GRID loop","how":"markItems[2] WALLPAPER wordmark on tile 2"},
  {"id":"text.brand-mark.4","where":"createNode/TILE GRID loop","how":"markItems[3] ESQUIRE wordmark on tile 3"},
  {"id":"text.brand-mark.5","where":"createNode/TILE GRID loop","how":"markItems[4] WIRED wordmark on tile 4"},
  {"id":"text.brand-mark.6","where":"createNode/TILE GRID loop","how":"markItems[5] FINANCIAL TIMES wordmark on tile 5"},
